use strict; use warnings;
my ($a,$b); my $h;
open my $fh,'<','/app/sequences.fasta' or die $!;
while(<$fh>){ chomp; if(/^>(\S+)/){$h=$1; next} s/\s+//g; $a .= $_ if $h eq 'input'; $b .= $_ if $h eq 'output'; }
my $i=0; $i++ while substr($a,$i,1) eq substr($b,$i,1);
my $ea=length($a)-1; my $eb=length($b)-1; while($ea >= $i && $eb >= $i && substr($a,$ea,1) eq substr($b,$eb,1)){--$ea;--$eb;}
my $p=substr($a,0,$i); my $q=substr($a,$i); my $ins=substr($b,$i,$eb-$i+1);
sub rc { my $x=reverse shift; $x =~ tr/ACGT/TGCA/; return $x; }
sub tm { my ($s)=@_; my $out=`/tmp/primer3/usr/bin/oligotm -tp 1 -sc 1 -mv 50 -dv 2 -n 0.8 -d 500 $s`; chomp $out; return $out; }
print "boundary=$i insertion=$ins len=",length($ins),"\n";
print "left context=",substr($p,-50),"\nright context=",substr($q,0,50),"\n\n";
print "L\tF_anneal\tF_Tm\tR_anneal\tR_Tm\tdiff\n";
for my $l (15..36){
  my $f=substr($q,0,$l); my $r=rc(substr($p,-$l)); my $tf=tm($f); my $tr=tm($r); my $d=abs($tf-$tr);
  printf "%d\t%s\t%.6f\t%s\t%.6f\t%.6f\n",$l,$f,$tf,$r,$tr,$d;
}
PERL
perl /tmp/design.pl

